from drive_parts import P, R, B, bar, flame, kite, ngon, rect, rot, mov, scl, mir, arcpts
from models2 import star5, qmark, cross_x, mine_body


def ca(a):
    return math.cos(math.radians(a)), math.sin(math.radians(a))


def arrowhead(tip, ang, L, w, **kw):
    """A triangle arrowhead with its point at `tip`, flying toward `ang`."""
    c, s = ca(ang)
    bx, by = tip[0] - c*L, tip[1] - s*L
    return P([tip, (bx - s*w, by + c*w), (bx + s*w, by - c*w)], bev=.6, **kw)


